def is_submodule_included(src, tgt):
    """Check that the tgt's submodule is included by src, if they belong
    to the same module."""
    if not src.module == tgt.module:
        return False
    src_path = src.module.path
    tgt_path = tgt.module.path
    return any(tgt_path.startswith(p) for p in src_path)

