def is_submodule_imported(src, tgt):
    """Check that the tgt's submodule is imported by src, if they belong
    to the same module."""
    if not src.module == tgt.module:
        return False
    src_path = src.module.path
    tgt_path = tgt.module.path
    return any(tgt_path.startswith(p) for p in src_path)


def get_module_path_from_module(module):
    """Get the path of the given module."""
    if not module:
        return None
    return module.path


def get_module_path_from_node(node):
    """Get the path of the module containing the given node."""
    if not node:
        return None
    return get_module_path_from_module(node.module)


